<?php
declare(strict_types=1);
require __DIR__ . '/../config.php';require __DIR__ . '/../helpers.php';require_admin();$profile=business_profile($pdo);$productId=filter_input(INPUT_GET,'product_id',FILTER_VALIDATE_INT);
$products=$pdo->query("SELECT p.id,p.name,p.price,p.is_active,c.name category_name,
COALESCE(SUM(CASE WHEN o.status='paid' THEN oi.quantity ELSE 0 END),0) total_qty,
COALESCE(SUM(CASE WHEN o.status='paid' THEN oi.unit_price*oi.quantity ELSE 0 END),0) revenue,
COALESCE(SUM(CASE WHEN o.status='paid' AND DATE(o.closed_at)=CURDATE() THEN oi.quantity ELSE 0 END),0) today_qty,
COUNT(DISTINCT CASE WHEN o.status='paid' THEN o.id END) bill_count
FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN order_items oi ON oi.product_id=p.id LEFT JOIN orders o ON o.id=oi.order_id
GROUP BY p.id,p.name,p.price,p.is_active,c.name ORDER BY total_qty DESC,p.name")->fetchAll();
$detail=null;$recent=[];$daily=[];$summary=null;if($productId){$stmt=$pdo->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=?');$stmt->execute([$productId]);$detail=$stmt->fetch();if($detail){$stmt=$pdo->prepare("SELECT COALESCE(SUM(oi.quantity),0) qty,COALESCE(SUM(oi.unit_price*oi.quantity),0) revenue,COUNT(DISTINCT o.id) bills,
COALESCE(SUM(CASE WHEN DATE(o.closed_at)=CURDATE() THEN oi.quantity ELSE 0 END),0) today_qty,
COALESCE(SUM(CASE WHEN YEAR(o.closed_at)=YEAR(CURDATE()) AND MONTH(o.closed_at)=MONTH(CURDATE()) THEN oi.quantity ELSE 0 END),0) month_qty
FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_id=? AND o.status='paid'");$stmt->execute([$productId]);$summary=$stmt->fetch();$stmt=$pdo->prepare("SELECT DATE(o.closed_at) sale_date,SUM(oi.quantity) qty,SUM(oi.unit_price*oi.quantity) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_id=? AND o.status='paid' AND o.closed_at>=DATE_SUB(CURDATE(),INTERVAL 60 DAY) GROUP BY DATE(o.closed_at) ORDER BY sale_date DESC");$stmt->execute([$productId]);$daily=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT o.id order_id,t.table_no,oi.quantity,oi.unit_price,(oi.unit_price*oi.quantity) line_total,o.closed_at FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN cafe_tables t ON t.id=o.table_id WHERE oi.product_id=? AND o.status='paid' ORDER BY o.closed_at DESC LIMIT 40");$stmt->execute([$productId]);$recent=$stmt->fetchAll();}}
$activePage='stats';$pageTitle='Ürün Satış Analizi';require __DIR__ . '/_top.php';
?>
<section class="admin-heading"><div><div class="eyebrow">Satış Analizi</div><h1 class="admin-title">Hangi üründen kaç tane?</h1><p class="muted">Tüm kapanmış hesaplar üzerinden ürün bazında adet, ciro ve satış detaylarını gör.</p></div><?php if($detail):?><a class="btn btn-ghost" href="product_stats.php">← Tüm ürünler</a><?php endif;?></section>
<?php if($detail&&$summary):?><section class="panel product-detail-hero"><div><div class="eyebrow"><?= e($detail['category_name']) ?></div><h2><?= e($detail['name']) ?></h2><p class="muted">Güncel menü fiyatı: <?= money((float)$detail['price']) ?></p></div><span class="badge <?= (int)$detail['is_active']?'success':'' ?>"><?= (int)$detail['is_active']?'Aktif':'Pasif' ?></span></section><section class="finance-grid compact"><article class="finance-card"><span>Bugün</span><strong><?= (int)$summary['today_qty'] ?> adet</strong></article><article class="finance-card"><span>Bu ay</span><strong><?= (int)$summary['month_qty'] ?> adet</strong></article><article class="finance-card"><span>Toplam</span><strong><?= (int)$summary['qty'] ?> adet</strong><small><?= (int)$summary['bills'] ?> farklı hesap</small></article><article class="finance-card highlight"><span>Toplam ürün cirosu</span><strong><?= money((float)$summary['revenue']) ?></strong></article></section><section class="dashboard-grid"><div class="panel"><div class="panel-title"><div><div class="eyebrow">Son 60 Gün</div><h2>Günlük satış</h2></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Adet</th><th>Ciro</th></tr></thead><tbody><?php if(!$daily):?><tr><td colspan="3" class="muted">Satış yok.</td></tr><?php endif;?><?php foreach($daily as $r):?><tr><td><?= e(date('d.m.Y',strtotime($r['sale_date']))) ?></td><td><strong><?= (int)$r['qty'] ?></strong></td><td><?= money((float)$r['revenue']) ?></td></tr><?php endforeach;?></tbody></table></div></div><div class="panel"><div class="panel-title"><div><div class="eyebrow">Detay</div><h2>Son satışlar</h2></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Adisyon</th><th>Masa</th><th>Adet</th><th>Fiyat</th><th>Tarih</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td>#<?= (int)$r['order_id'] ?></td><td>Masa <?= (int)$r['table_no'] ?></td><td><?= (int)$r['quantity'] ?></td><td><?= money((float)$r['line_total']) ?></td><td><?= e(date('d.m.Y H:i',strtotime($r['closed_at']))) ?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php else:?><section class="panel"><div class="panel-title"><div><div class="eyebrow">Tüm Zamanlar</div><h2>Ürün satış tablosu</h2></div><span class="badge gold"><?= count($products) ?> ürün</span></div><div class="table-wrap"><table class="data-table clickable-table"><thead><tr><th>Ürün</th><th>Kategori</th><th>Bugün</th><th>Toplam Adet</th><th>Hesap Sayısı</th><th>Ürün Cirosu</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?= e($p['name']) ?></strong></td><td><?= e($p['category_name']) ?></td><td><?= (int)$p['today_qty'] ?></td><td><strong><?= (int)$p['total_qty'] ?> adet</strong></td><td><?= (int)$p['bill_count'] ?></td><td><?= money((float)$p['revenue']) ?></td><td><a class="btn btn-sm" href="product_stats.php?product_id=<?= (int)$p['id'] ?>">Detay</a></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php require __DIR__ . '/_bottom.php'; ?>
